/** DOM HUD: bars, ship panel, inventory, minimap, chat log, toasts. */

import * as C from '../shared/constants';
import { FACTIONS, ITEMS, RARITY_COLORS, FRUITS } from '../shared/content';
import type { PlayerState, Snapshot } from '../shared/types';

const $ = <T extends HTMLElement>(id: string): T => document.getElementById(id) as T;

export class Hud {
  private hpFill = $<HTMLDivElement>('hp-fill');
  private hpText = $<HTMLSpanElement>('hp-text');
  private xpFill = $<HTMLDivElement>('xp-fill');
  private xpText = $<HTMLSpanElement>('xp-text');
  private nameTag = $<HTMLSpanElement>('name-tag');
  private factionTag = $<HTMLSpanElement>('faction-tag');
  private levelTag = $<HTMLSpanElement>('level-tag');
  private shipHull = $<HTMLElement>('ship-hull');
  private shipCannons = $<HTMLElement>('ship-cannons');
  private shipCrew = $<HTMLElement>('ship-crew');
  private gold = $<HTMLElement>('gold');
  private bounty = $<HTMLElement>('bounty');
  private inventory = $<HTMLUListElement>('inventory');
  private skillSlot = $<HTMLDivElement>('skill-slot');
  private skillName = $<HTMLSpanElement>('skill-name');
  private skillCd = $<HTMLDivElement>('skill-cd');
  private dockHint = $<HTMLDivElement>('dock-hint');
  private chatlog = $<HTMLDivElement>('chatlog');
  private toastEl = $<HTMLDivElement>('toast');
  private minimap = $<HTMLCanvasElement>('minimap');

  private toastTimer = 0;
  private lastInvKey = '';

  show(): void {
    $('hud').classList.remove('hidden');
  }

  update(p: PlayerState, now: number): void {
    const hpRatio = Math.max(0, Math.min(1, p.hp / p.maxHp));
    this.hpFill.style.width = `${hpRatio * 100}%`;
    this.hpText.textContent = `${Math.ceil(p.hp)}/${Math.round(p.maxHp)}`;

    const xpRatio = Math.max(0, Math.min(1, p.xp / p.xpNext));
    this.xpFill.style.width = `${xpRatio * 100}%`;
    this.xpText.textContent = `${Math.floor(p.xp)}/${p.xpNext}`;

    this.nameTag.textContent = p.name;
    this.factionTag.textContent = FACTIONS[p.faction].name;
    this.factionTag.className = `tag ${p.faction}`;
    this.levelTag.textContent = `Lv ${p.level}`;

    this.shipHull.textContent = String(p.ship.hull);
    this.shipCannons.textContent = String(p.ship.cannons);
    this.shipCrew.textContent = String(p.ship.crew);
    this.gold.textContent = String(p.gold);
    this.bounty.textContent = String(p.bounty);

    const invKey = p.inventory.map((s) => `${s.itemId}:${s.count}`).join('|');
    if (invKey !== this.lastInvKey) {
      this.lastInvKey = invKey;
      this.inventory.innerHTML = '';
      if (p.inventory.length === 0) {
        const li = document.createElement('li');
        li.innerHTML = '<span>Leer</span><span>—</span>';
        this.inventory.appendChild(li);
      }
      for (const stack of p.inventory) {
        const def = ITEMS[stack.itemId];
        if (!def) continue;
        const li = document.createElement('li');
        li.innerHTML = `<span style="color:${RARITY_COLORS[def.rarity]}">${def.name}</span><span>${stack.count}</span>`;
        this.inventory.appendChild(li);
      }
    }

    // Skill slot
    const fruit = p.fruit ? FRUITS[p.fruit] : null;
    const unlocked = !!fruit && p.level >= fruit.unlockLevel;
    this.skillSlot.classList.toggle('locked', !unlocked);
    this.skillName.textContent = fruit
      ? unlocked
        ? `Urkraft: ${fruit.skill.name}`
        : `Urkraft: ${fruit.name} (Lv ${fruit.unlockLevel})`
      : 'Urkraft: keine Frucht';

    const cd = fruit ? fruit.skill.cooldownMs : 0;
    const remaining = fruit ? Math.max(0, cd - (now - p.lastSkillAt)) : 0;
    this.skillCd.style.transform = `scaleX(${cd ? remaining / cd : 0})`;
  }

  setDockHint(show: boolean): void {
    this.dockHint.classList.toggle('hidden', !show);
  }

  pushChat(text: string, cls = 'sys'): void {
    const line = document.createElement('div');
    line.className = cls;
    line.textContent = text;
    this.chatlog.appendChild(line);
    while (this.chatlog.childElementCount > 9) this.chatlog.firstElementChild?.remove();
  }

  toast(text: string): void {
    this.toastEl.textContent = text;
    this.toastEl.classList.add('show');
    window.clearTimeout(this.toastTimer);
    this.toastTimer = window.setTimeout(() => this.toastEl.classList.remove('show'), 2600);
  }

  drawMinimap(snapshot: Snapshot, localId: string): void {
    const ctx = this.minimap.getContext('2d');
    if (!ctx) return;
    const size = this.minimap.width;
    const cx = size / 2;
    const cy = size / 2;
    const R = size / 2 - 4;
    const scale = R / C.WORLD_RADIUS;

    ctx.clearRect(0, 0, size, size);

    // Ocean
    ctx.fillStyle = 'rgba(12, 52, 78, 0.85)';
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.fill();

    // Island
    ctx.fillStyle = '#3f6b34';
    ctx.beginPath();
    ctx.arc(cx, cy, C.ISLAND_RADIUS * scale, 0, Math.PI * 2);
    ctx.fill();

    // Cave
    ctx.fillStyle = '#12161a';
    ctx.beginPath();
    ctx.arc(cx + C.CAVE.x * scale, cy + C.CAVE.z * scale, 3, 0, Math.PI * 2);
    ctx.fill();

    // Dock
    ctx.fillStyle = '#e8c37a';
    ctx.fillRect(cx + C.DOCK.x * scale - 2, cy + C.DOCK.z * scale - 2, 4, 4);

    // NPCs
    for (const n of snapshot.npcs) {
      if (!n.alive) continue;
      ctx.fillStyle = n.type === 'boss_kraken' ? '#c07bff' : '#ff9c5a';
      ctx.beginPath();
      ctx.arc(cx + n.x * scale, cy + n.z * scale, n.type === 'boss_kraken' ? 3 : 2, 0, Math.PI * 2);
      ctx.fill();
    }

    // Players
    for (const p of snapshot.players) {
      if (!p.alive) continue;
      const self = p.id === localId;
      ctx.fillStyle = self ? '#7dffb0' : p.faction === 'pirate' ? '#ff6b5e' : '#7ec8ff';
      ctx.beginPath();
      ctx.arc(cx + p.x * scale, cy + p.z * scale, self ? 3.5 : 2.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Border
    ctx.strokeStyle = 'rgba(232, 195, 122, 0.45)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.stroke();
  }
}

/** Keyboard, mouse and touch input. Produces intent flags only. */

export interface InputHandlers {
  attack(): void;
  skill(): void;
  dock(): void;
  respawn(): void;
  chat(text: string): void;
}

type AimResolver = (clientX: number, clientY: number) => { x: number; z: number };

export class Input {
  up = false;
  down = false;
  left = false;
  right = false;
  aimX = 0;
  aimZ = 1;
  seq = 0;
  chatMode = false;

  private mouseX = window.innerWidth / 2;
  private mouseY = window.innerHeight / 2;
  private chatEl: HTMLInputElement;
  private stick = { active: false, id: -1, ox: 0, oy: 0, dx: 0, dy: 0 };

  constructor(
    private canvas: HTMLCanvasElement,
    private resolveAim: AimResolver,
    private handlers: InputHandlers,
  ) {
    this.chatEl = document.createElement('input');
    this.chatEl.id = 'chat-input';
    this.chatEl.className = 'hidden';
    this.chatEl.maxLength = 140;
    this.chatEl.placeholder = 'Nachricht… (Enter zum Senden, Esc zum Abbrechen)';
    this.chatEl.autocomplete = 'off';
    Object.assign(this.chatEl.style, {
      position: 'fixed',
      left: '50%',
      bottom: '24px',
      transform: 'translateX(-50%)',
      width: 'min(520px, 80vw)',
      padding: '10px 14px',
      borderRadius: '10px',
      border: '1px solid rgba(232,195,122,0.5)',
      background: 'rgba(8,14,20,0.94)',
      color: '#fff',
      fontSize: '14px',
      outline: 'none',
      zIndex: '40',
      pointerEvents: 'auto',
    } as CSSStyleDeclaration);
    document.body.appendChild(this.chatEl);

    this.bindKeyboard();
    this.bindMouse();
    this.bindTouch();
  }

  private bindKeyboard(): void {
    window.addEventListener('keydown', (e) => {
      if (this.chatMode) {
        if (e.key === 'Escape') this.closeChat();
        return;
      }
      switch (e.code) {
        case 'KeyW':
        case 'ArrowUp':
          this.up = true;
          break;
        case 'KeyS':
        case 'ArrowDown':
          this.down = true;
          break;
        case 'KeyA':
        case 'ArrowLeft':
          this.left = true;
          break;
        case 'KeyD':
        case 'ArrowRight':
          this.right = true;
          break;
        case 'KeyQ':
          this.handlers.skill();
          break;
        case 'KeyE':
          this.handlers.dock();
          break;
        case 'Enter':
          e.preventDefault();
          this.openChat();
          break;
        case 'Space':
          e.preventDefault();
          this.handlers.respawn();
          break;
        default:
          break;
      }
      if (e.code.startsWith('Arrow')) e.preventDefault();
    });

    window.addEventListener('keyup', (e) => {
      switch (e.code) {
        case 'KeyW':
        case 'ArrowUp':
          this.up = false;
          break;
        case 'KeyS':
        case 'ArrowDown':
          this.down = false;
          break;
        case 'KeyA':
        case 'ArrowLeft':
          this.left = false;
          break;
        case 'KeyD':
        case 'ArrowRight':
          this.right = false;
          break;
        default:
          break;
      }
    });

    window.addEventListener('blur', () => {
      this.up = this.down = this.left = this.right = false;
    });
  }

  private bindMouse(): void {
    this.canvas.addEventListener('pointermove', (e) => {
      if (e.pointerType !== 'mouse') return;
      this.mouseX = e.clientX;
      this.mouseY = e.clientY;
    });

    this.canvas.addEventListener('pointerdown', (e) => {
      if (e.pointerType !== 'mouse' || e.button !== 0) return;
      this.mouseX = e.clientX;
      this.mouseY = e.clientY;
      this.handlers.attack();
    });

    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  private bindTouch(): void {
    const isTouch = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    if (!isTouch) return;

    this.canvas.addEventListener(
      'touchstart',
      (e) => {
        e.preventDefault();
        for (const t of Array.from(e.changedTouches)) {
          if (t.clientX < window.innerWidth / 2 && !this.stick.active) {
            this.stick = { active: true, id: t.identifier, ox: t.clientX, oy: t.clientY, dx: 0, dy: 0 };
          } else if (t.clientX >= window.innerWidth / 2) {
            this.mouseX = t.clientX;
            this.mouseY = t.clientY;
            this.handlers.attack();
          }
        }
      },
      { passive: false },
    );

    this.canvas.addEventListener(
      'touchmove',
      (e) => {
        e.preventDefault();
        for (const t of Array.from(e.changedTouches)) {
          if (!this.stick.active || t.identifier !== this.stick.id) continue;
          this.stick.dx = t.clientX - this.stick.ox;
          this.stick.dy = t.clientY - this.stick.oy;
          const max = 55;
          this.stick.dx = Math.max(-max, Math.min(max, this.stick.dx));
          this.stick.dy = Math.max(-max, Math.min(max, this.stick.dy));
        }
      },
      { passive: false },
    );

    const end = (e: TouchEvent) => {
      for (const t of Array.from(e.changedTouches)) {
        if (this.stick.active && t.identifier === this.stick.id) {
          this.stick = { active: false, id: -1, ox: 0, oy: 0, dx: 0, dy: 0 };
        }
      }
    };
    this.canvas.addEventListener('touchend', end);
    this.canvas.addEventListener('touchcancel', end);

    this.makeTouchButton('Q', () => this.handlers.skill(), 'right', '110px');
    this.makeTouchButton('E', () => this.handlers.dock(), 'right', '56px');
  }

  private makeTouchButton(label: string, fn: () => void, side: 'left' | 'right', bottom: string): void {
    const btn = document.createElement('button');
    btn.textContent = label;
    Object.assign(btn.style, {
      position: 'fixed',
      [side]: '20px',
      bottom,
      width: '52px',
      height: '52px',
      borderRadius: '50%',
      border: '1px solid rgba(232,195,122,0.5)',
      background: 'rgba(10,18,26,0.8)',
      color: '#e8c37a',
      fontSize: '16px',
      fontWeight: '700',
      zIndex: '25',
      pointerEvents: 'auto',
    } as CSSStyleDeclaration);
    btn.addEventListener('touchstart', (e) => {
      e.preventDefault();
      fn();
    });
    document.body.appendChild(btn);
  }

  private openChat(): void {
    this.chatMode = true;
    this.chatEl.classList.remove('hidden');
    this.chatEl.value = '';
    this.chatEl.focus();
  }

  private closeChat(): void {
    this.chatMode = false;
    this.chatEl.classList.add('hidden');
    this.chatEl.value = '';
    this.chatEl.blur();
  }

  /** Called once per network tick. */
  sample(): { up: boolean; down: boolean; left: boolean; right: boolean; aimX: number; aimZ: number; seq: number } {
    const aim = this.resolveAim(this.mouseX, this.mouseY);
    this.aimX = aim.x;
    this.aimZ = aim.z;
    this.seq += 1;

    if (this.stick.active) {
      const dead = 12;
      const dx = this.stick.dx;
      const dy = this.stick.dy;
      this.left = dx < -dead;
      this.right = dx > dead;
      this.up = dy < -dead;
      this.down = dy > dead;
    }

    return { up: this.up, down: this.down, left: this.left, right: this.right, aimX: this.aimX, aimZ: this.aimZ, seq: this.seq };
  }

  bindChatSubmit(fn: (text: string) => void): void {
    this.chatEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const text = this.chatEl.value.trim();
        if (text) fn(text);
        this.closeChat();
      } else if (e.key === 'Escape') {
        this.closeChat();
      }
      e.stopPropagation();
    });
  }
}

/**
 * Client entry point.
 *
 * Responsibilities:
 *  - menu / connection lifecycle
 *  - client-side prediction for the local ship (instant response)
 *  - reconciliation against the authoritative snapshot
 *  - 20 Hz input uplink
 */

import * as C from '../shared/constants';
import { FACTIONS } from '../shared/content';
import { dist2, normalize } from '../shared/math';
import type { FactionId, PlayerState, Snapshot } from '../shared/types';
import { GameView } from './scene';
import { Hud } from './hud';
import { Input } from './input';
import { Net } from './net';

const $ = <T extends HTMLElement>(id: string): T => document.getElementById(id) as T;

const menu = $('menu');
const loading = $('loading');
const nameInput = $<HTMLInputElement>('input-name');
const playBtn = $<HTMLButtonElement>('btn-play');

let faction: FactionId = 'pirate';

for (const btn of Array.from(document.querySelectorAll<HTMLButtonElement>('.faction-btn'))) {
  btn.addEventListener('click', () => {
    faction = (btn.dataset.faction as FactionId) ?? 'pirate';
    for (const other of Array.from(document.querySelectorAll('.faction-btn'))) other.classList.remove('selected');
    btn.classList.add('selected');
  });
}

nameInput.value = localStorage.getItem('pirate-slice-name') ?? '';
nameInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') playBtn.click();
});

let started = false;

playBtn.addEventListener('click', () => {
  if (started) return;
  started = true;

  const name = (nameInput.value.trim() || `Kapitän${Math.floor(Math.random() * 900 + 100)}`).slice(0, 16);
  localStorage.setItem('pirate-slice-name', name);

  menu.classList.add('hidden');
  loading.classList.remove('hidden');
  start(name, faction);
});

function start(name: string, chosenFaction: FactionId): void {
  const canvas = $<HTMLCanvasElement>('game');
  const view = new GameView(canvas);
  const hud = new Hud();
  const net = new Net();

  const local = { x: 0, z: 0, rot: 0, alive: true };
  let latest: Snapshot | null = null;
  let playerId = '';

  const input = new Input(canvas, (x, y) => view.aimPoint(x, y), {
    attack: () => net.attack(),
    skill: () => net.skill(),
    dock: () => net.dock('cannons'),
    respawn: () => net.respawn(),
    chat: (text) => net.chat(text),
  });
  input.bindChatSubmit((text) => net.chat(text));

  net.onWelcome = (msg) => {
    playerId = msg.playerId;
    view.setLocalId(playerId);
    latest = msg.snapshot;

    const me = msg.snapshot.players.find((p) => p.id === playerId);
    if (me) {
      local.x = me.x;
      local.z = me.z;
      local.rot = me.rot;
      local.alive = me.alive;
    }

    loading.classList.add('hidden');
    hud.show();
    hud.pushChat(`Willkommen, ${name}. Fraktion: ${FACTIONS[chosenFaction].name}.`, 'sys');
    hud.pushChat('Segle zu den Marine-Patrouillen östlich der Insel oder zum Tiefenwächter in der Höhle.', 'sys');
    hud.toast(`Willkommen an Bord, ${name}!`);
  };

  net.onSnapshot = (msg) => {
    latest = msg.snapshot;
    const me = msg.snapshot.players.find((p) => p.id === playerId);
    if (!me) return;

    local.alive = me.alive;
    if (!me.alive) {
      local.x = me.x;
      local.z = me.z;
    } else {
      // Reconciliation: snap on big divergence, otherwise ease toward authority.
      const d = dist2(local.x, local.z, me.x, me.z);
      if (d > 70) {
        local.x = me.x;
        local.z = me.z;
        local.rot = me.rot;
      } else {
        local.x += (me.x - local.x) * 0.12;
        local.z += (me.z - local.z) * 0.12;
      }
    }

    view.sync(msg.snapshot, playerId);
    hud.update(me, Date.now());
    hud.drawMinimap(msg.snapshot, playerId);

    const nearDock = me.alive && dist2(me.x, me.z, C.DOCK.x, C.DOCK.z) < C.DOCK_RADIUS;
    hud.setDockHint(nearDock);
  };

  net.onEvent = (msg) => {
    hud.pushChat(msg.text, msg.kind === 'loot' ? 'loot' : msg.kind === 'levelup' ? 'lvl' : 'sys');
    if (msg.kind === 'levelup' || msg.kind === 'death') hud.toast(msg.text);
  };

  net.onChat = (msg) => {
    hud.pushChat(`[${msg.from}] ${msg.text}`, 'chat');
  };

  net.onLevelup = (level) => {
    hud.toast(`Level ${level} erreicht!`);
  };

  net.onError = (text) => hud.toast(text);

  net.onStatus = (text) => {
    if (!latest) {
      const p = loading.querySelector('p');
      if (p) p.textContent = text;
    } else {
      hud.pushChat(text, 'sys');
    }
  };

  net.connect(name, chosenFaction);

  // ---- local prediction + render loop -------------------------------------
  let last = performance.now();
  let hudAccum = 0;

  const frame = (now: number) => {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (local.alive) {
      const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
      const dz = (input.down ? 1 : 0) - (input.up ? 1 : 0);
      if (dx !== 0 || dz !== 0) {
        const dir = normalize(dx, dz);
        local.x += dir.x * C.PLAYER_SPEED * dt;
        local.z += dir.z * C.PLAYER_SPEED * dt;
        local.rot = Math.atan2(dir.x, dir.z);
      }
      const r = Math.hypot(local.x, local.z);
      if (r > C.WORLD_RADIUS) {
        local.x = (local.x / r) * C.WORLD_RADIUS;
        local.z = (local.z / r) * C.WORLD_RADIUS;
      }
    }

    if (playerId) view.setLocalPosition(playerId, local.x, local.z, local.rot, local.alive);
    view.render(local);

    hudAccum += dt;
    if (hudAccum > 0.25 && latest) {
      hudAccum = 0;
      hud.drawMinimap(latest, playerId);
    }

    requestAnimationFrame(frame);
  };
  requestAnimationFrame(frame);

  // ---- input uplink -------------------------------------------------------
  setInterval(() => {
    if (!net.connected) return;
    net.sendInput(input.sample());
  }, C.TICK_MS);
}

